#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import fingroup.fingroup finset ssrnat zmodp. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section Putnam_1994_A5. Variable n : nat. Hypothesis n_eq_11 : n = 11. Definition pos := (sigT (fun k : nat => k.+1 <= n.+1)) * nat. Definition bottom_row := 'I_n -> 'I_2. Definition triangle_entry (a : bottom_row) : forall k : nat, k.+1 <= n.+1 -> 'I_(k.+1) -> int := fix entry k (Hk : k.+1 <= n.+1) (i : 'I_(k.+1)) {struct k} := if k == n.-1 then (a i)%:Z else let Hkp1 : k.+2 <= n.+1 := leq_trans (ltnW (ltnSn _)) Hk in (entry a k.+1 Hkp1 (widen_ord (leq_trans (ltnW (ltnSn _)) i)) + entry a k.+1 Hkp1 (widen_ord (leq_trans (ltnW (ltnSn _)) (inord (i.+1 mod (k.+2))))))%Z. End
